  {
    id: "customers",
    label: "客户",
    icon: UsersIcon,
    tree: [
      {
        id: "workspace",
        label: "客户工作区",
        status: "active",
        children: [
          {
            id: "views",
            label: "客户视图",
            icon: FolderIcon,
            children: [
