      },
      {
        id: "growth",
        label: "增长项目",
        status: "paused",
        children: [
          { id: "research", label: "客户调研", href: "/growth/research" },
        ],
      },
      {
        id: "archive",
        label: "往期合作",
        status: "archived",
        children: [{ id: "past", label: "历史记录", href: "/archive/past" }],
