}
export { DEFAULT_MODULES, DEFAULT_USAGE }

"use client"

import * as React from "react"

import { useState } from "react"

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Separator } from "@/components/ui/separator"
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/ui/sidebar"
import { Sidebar03 } from "@/components/sidebar-03/sidebar-03"
import { DEFAULT_MODULES } from "@/components/sidebar-03/nav-data"
import { findPath } from "@/components/sidebar-03/tree"
import {
  GridContainer,
  GridSection,
  GridSeparator,
} from "@/components/ui/grid-layout/grid-layout"

/** 主区的占位内容：真实项目里换成各页面自己的内容。 */
const SUMMARY = [
  { label: "本周活跃成员", value: "128" },
  { label: "已完成任务", value: "342" },
  { label: "待处理评论", value: "17" },
]
const RECENT = [
  "苏晓宁 更新了「官网改版」的设计稿",
  "周明远 在「增长实验」里新增了 2 个对照组",
  "陈知夏 完成了 5 个任务",
  "韩若溪 邀请了新成员加入团队",
]
export default function Sidebar03Page() {
  const [activeItemId, setActiveItemId] = useState("all")
  const [moduleId, setModuleId] = useState("customers")
  const currentModule = DEFAULT_MODULES.find((item) => item.id === moduleId)
  const path = findPath(currentModule?.tree ?? [], activeItemId)
  const current = path.at(-1)
  const team = { name: "客户协作空间" }
  return (
    <SidebarProvider defaultOpen>
      <Sidebar03
        moduleId={moduleId}
        onModuleChange={setModuleId}
        activeNodeId={activeItemId}
        navigation={{
          intercept: true,
          onNavigate: ({ nodeId }) => {
            if (nodeId) setActiveItemId(nodeId)
          },
        }}
      />
      <SidebarInset>
        <header className="sticky top-0 z-10 flex h-14 shrink-0 items-center gap-2 border-b border-edge bg-background px-4">
          <SidebarTrigger className="-ml-1" aria-label="切换侧栏" />
          <Separator
            orientation="vertical"
            className="mr-1 data-vertical:h-4 data-vertical:self-center"
          />
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem className="hidden sm:inline-flex">
                {currentModule?.label}
              </BreadcrumbItem>
              {path.map((node, index) => {
                const last = index === path.length - 1
                // 窄屏只留最后一级，避免面包屑挤满顶栏
                const hide = last ? undefined : "hidden sm:inline-flex"
                return (
                  <React.Fragment key={node.id}>
                    <BreadcrumbSeparator className="hidden sm:block" />
                    <BreadcrumbItem className={hide}>
                      {last ? (
                        <BreadcrumbPage>{node.label}</BreadcrumbPage>
                      ) : (
                        node.label
                      )}
                    </BreadcrumbItem>
                  </React.Fragment>
                )
              })}
            </BreadcrumbList>
          </Breadcrumb>
        </header>
        <GridContainer className="min-h-[calc(100svh-3.5rem)] [--grid-width:60rem]">
          <GridSection className="px-4 py-6 sm:px-6">
            <h1 className="text-xl font-semibold tracking-tight">
              {current?.label ?? currentModule?.label}
            </h1>
            <p className="mt-1 text-sm leading-7 text-muted-foreground">
              这是{team?.name}的工作区，下面是一些占位内容。
            </p>
          </GridSection>
          <GridSection>
            <dl className="grid divide-y divide-dashed divide-edge sm:grid-cols-3 sm:divide-x sm:divide-y-0">
              {SUMMARY.map((stat) => (
                <div key={stat.label} className="px-4 py-5 sm:px-6">
                  <dt className="text-xs text-muted-foreground">
                    {stat.label}
                  </dt>
                  <dd className="mt-1 font-mono text-2xl tabular-nums">
                    {stat.value}
                  </dd>
                </div>
              ))}
            </dl>
          </GridSection>
          <GridSeparator />
          <GridSection>
            <ul className="divide-y divide-dashed divide-edge">
              {RECENT.map((entry) => (
                <li key={entry} className="px-4 py-3 text-sm leading-7 sm:px-6">
                  {entry}
                </li>
              ))}
            </ul>
          </GridSection>
        </GridContainer>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"
import * as React from "react"
import {
  LayersIcon,
  PlusIcon,
  EllipsisIcon,
  CircleHelpIcon,
  SettingsIcon,
  LogOutIcon,
} from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Sidebar,
  SidebarContent,
  SidebarInput,
  useSidebar,
} from "@/components/ui/sidebar"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from "@/components/ui/dropdown-menu"
import { useControllableState } from "@/hooks/use-controllable-state"
import { DEFAULT_LABELS, type Sidebar03Labels } from "./config"
import { DEFAULT_MODULES, DEFAULT_USAGE } from "./nav-data"
import { Sidebar03Tree, findPath } from "./tree"
import type {
  Sidebar03Module,
  Sidebar03TreeNode,
  Sidebar03Usage,
  Sidebar03Navigation,
  Sidebar03Link,
} from "./types"

type Sidebar03Props = Omit<
  React.ComponentProps<typeof Sidebar>,
  "children" | "collapsible"
> & {
  /** 模块与树数据；默认中文示例。 */
  modules?: Sidebar03Module[]
  /** 受控模块 id。 */
  moduleId?: string
  /** 初始模块；默认第一个。 */
  defaultModuleId?: string
  onModuleChange?: (id: string) => void
  /** 当前页面节点。 */
  activeNodeId?: string
  /** 初始展开节点；默认包含当前节点的祖先。 */
  defaultExpandedIds?: string[]
  /** 受控展开节点，跨模块 id 必须唯一。 */
  expandedIds?: string[]
  onExpandedChange?: (ids: string[]) => void
  /** 底部用量；默认 9.2 GB / 10 GB。 */
  usage?: Sidebar03Usage
  /** 链接组件；默认 a。 */
  linkComponent?: Sidebar03Link
  navigation?: Sidebar03Navigation
  labels?: Partial<Sidebar03Labels>
  onCreate?: (payload: { moduleId: string }) => void
  onUtilityAction?: (payload: {
    action: "help" | "settings" | "signOut"
  }) => void
}
function Sidebar03({
  modules = DEFAULT_MODULES,
  moduleId,
  defaultModuleId,
  onModuleChange,
  activeNodeId,
  expandedIds,
  defaultExpandedIds = [],
  onExpandedChange,
  usage = DEFAULT_USAGE,
  linkComponent: Link = "a",
  navigation,
  labels: labelsProp,
  onCreate,
  onUtilityAction,
  className,
  style,
  ...props
}: Sidebar03Props) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const { isMobile, state, setOpen, setOpenMobile } = useSidebar()
  const [currentId, setCurrentId] = useControllableState({
    prop: moduleId,
    defaultProp: defaultModuleId ?? modules[0]?.id ?? "",
    onChange: onModuleChange,
  })
  const current =
    modules.find((module) => module.id === currentId) ?? modules[0]
  const [expanded, setExpanded] = useControllableState({
    prop: expandedIds,
    defaultProp: [
      ...new Set([
        ...defaultExpandedIds,
        ...modules.flatMap((module) =>
          findPath(module.tree, activeNodeId)
            .slice(0, -1)
            .map((node) => node.id),
        ),
      ]),
    ],
    onChange: onExpandedChange,
  })
  const [query, setQuery] = React.useState("")
  function navigate(
    event: React.MouseEvent<HTMLAnchorElement>,
    href: string,
    nodeId?: string,
  ) {
    if (
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    )
      return
    if (navigation?.intercept) event.preventDefault()
    navigation?.onNavigate?.({ href, nodeId })
    if (isMobile) setOpenMobile(false)
  }
  function renderLink(node: Sidebar03TreeNode, content: React.ReactNode) {
    return (
      <Link
        href={node.href}
        tabIndex={-1}
        aria-current={node.id === activeNodeId ? "page" : undefined}
        onClick={(event: React.MouseEvent<HTMLAnchorElement>) =>
          navigate(event, node.href!, node.id)
        }
        {...(navigation?.intercept && Link !== "a" ? { prefetch: false } : {})}
        className="flex min-w-0 flex-1 items-center gap-2 pr-2"
      >
        {content}
      </Link>
    )
  }
  const percent =
    usage.total > 0
      ? Math.max(0, Math.min(100, (usage.used / usage.total) * 100))
      : 0
  return (
    <div
      data-slot="sidebar-03-shell"
      className="contents"
      style={
        {
          "--sidebar-width": "19rem",
          "--sidebar-width-icon": "3rem",
        } as React.CSSProperties
      }
    >
      <Sidebar
        data-slot="sidebar-03"
        collapsible="icon"
        className={cn("overflow-hidden", className)}
        style={
          {
            "--sidebar-width": "19rem",
            "--sidebar-width-icon": "3rem",
            ...style,
          } as React.CSSProperties
        }
        {...props}
      >
        <TooltipProvider>
          <div className="flex h-full min-h-0">
            <Sidebar
              collapsible="none"
              className="w-12 shrink-0 border-r border-sidebar-border"
            >
              <div
                data-slot="sidebar-03-brand"
                className="flex h-14 shrink-0 items-center justify-center border-b border-sidebar-border"
              >
                <Button
                  variant="ghost"
                  size="icon-sm"
                  aria-label={labels.brand}
                  onClick={() => setOpen(true)}
                >
                  <LayersIcon aria-hidden />
                </Button>
              </div>
              <nav
                aria-label={labels.modules}
                className="flex flex-1 flex-col items-center gap-2 py-3"
              >
                {modules.map((module) => (
                  <Tooltip key={module.id}>
                    <TooltipTrigger
                      render={
                        <Button
                          variant="ghost"
                          size="icon"
                          aria-label={module.label}
                          aria-pressed={module.id === current?.id}
                          className="aria-pressed:bg-sidebar-accent aria-pressed:text-sidebar-accent-foreground"
                          onClick={() => {
                            setCurrentId(module.id)
                            setQuery("")
                            if (!isMobile) setOpen(true)
                          }}
                        >
                          <module.icon aria-hidden />
                        </Button>
                      }
                    />
                    <TooltipContent side="right">{module.label}</TooltipContent>
                  </Tooltip>
                ))}
              </nav>
              <div className="flex flex-col items-center gap-2 border-t border-sidebar-border py-3">
                {(
                  [
                    { key: "help", icon: CircleHelpIcon },
                    { key: "settings", icon: SettingsIcon },
                    { key: "signOut", icon: LogOutIcon },
                  ] as const
                ).map(({ key, icon: Icon }) => (
                  <Tooltip key={key}>
                    <TooltipTrigger
                      render={
                        <Button
                          variant="ghost"
                          size="icon"
                          aria-label={labels[key]}
                          onClick={() => onUtilityAction?.({ action: key })}
                        >
                          <Icon aria-hidden />
                        </Button>
                      }
                    />
                    <TooltipContent side="right">{labels[key]}</TooltipContent>
                  </Tooltip>
                ))}
              </div>
            </Sidebar>
            {(isMobile || state === "expanded") && (
              <Sidebar collapsible="none" className="min-w-0 flex-1">
                <div
                  data-slot="sidebar-03-panel-header"
                  className="flex h-14 shrink-0 items-center gap-1 border-b border-sidebar-border px-3"
                >
                  <span className="min-w-0 flex-1 truncate text-sm font-semibold">
                    {current?.label}
                  </span>
                  <Button
                    variant="ghost"
                    size="icon-sm"
                    aria-label={labels.create}
                    onClick={() =>
                      current && onCreate?.({ moduleId: current.id })
                    }
                  >
                    <PlusIcon aria-hidden />
                  </Button>
                  <DropdownMenu>
                    <DropdownMenuTrigger
                      render={
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          aria-label={labels.more}
                        >
                          <EllipsisIcon aria-hidden />
                        </Button>
                      }
                    />
                    <DropdownMenuContent align="start">
                      {current?.actions?.length ? (
                        current.actions.map((action) => (
                          <DropdownMenuItem
                            key={action.id}
                            onClick={action.onSelect}
                          >
                            {action.label}
                          </DropdownMenuItem>
                        ))
                      ) : (
                        <DropdownMenuItem
                          onClick={() =>
                            onUtilityAction?.({ action: "settings" })
                          }
                        >
                          {labels.settings}
                        </DropdownMenuItem>
                      )}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
                <div className="border-b border-sidebar-border p-3">
                  <SidebarInput
                    aria-label={labels.search}
                    placeholder={labels.search}
                    value={query}
                    onChange={(event) => setQuery(event.target.value)}
                    className="text-base focus-visible:border-sidebar-ring focus-visible:ring-0 md:text-sm"
                  />
                </div>
                <SidebarContent>
                  {current && (
                    <Sidebar03Tree
                      key={current.id}
                      nodes={current.tree}
                      expanded={expanded}
                      onExpandedChange={setExpanded}
                      activeId={activeNodeId}
                      query={query}
                      labels={labels}
                      renderLink={renderLink}
                    />
                  )}
                </SidebarContent>
                <div className="space-y-3 border-t border-sidebar-border p-4 text-xs">
                  <div className="flex justify-between gap-2">
                    <span>{usage.label}</span>
                    {usage.href && (
                      <Link
                        href={usage.href}
                        className="underline underline-offset-4"
                        onClick={(event: React.MouseEvent<HTMLAnchorElement>) =>
                          navigate(event, usage.href!)
                        }
                      >
                        {labels.upgrade}
                      </Link>
                    )}
                  </div>
                  <div
                    role="progressbar"
                    aria-label={usage.label}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={percent}
                    className="h-1.5 overflow-hidden rounded-full bg-sidebar-accent"
                  >
                    <div
                      className="h-full bg-sidebar-primary"
                      style={{ width: `${percent}%` }}
                    />
                  </div>
                  <p className="text-sidebar-foreground/60 tabular-nums">
                    {labels.used} {usage.used} {usage.unit} / {usage.total}{" "}
                    {usage.unit}
                  </p>
                </div>
              </Sidebar>
            )}
          </div>
        </TooltipProvider>
      </Sidebar>
    </div>
  )
}
export { Sidebar03 }
export type { Sidebar03Props }

"use client"
import * as React from "react"
import { ChevronRightIcon, FolderIcon } from "lucide-react"
import { cn } from "@/lib/utils"
import type { Sidebar03Labels } from "./config"
import type { Sidebar03TreeNode } from "./types"

function findPath(
  nodes: Sidebar03TreeNode[],
  id?: string,
): Sidebar03TreeNode[] {
  for (const node of nodes) {
    if (node.id === id) return [node]
    const path = findPath(node.children ?? [], id)
    if (path.length) return [node, ...path]
  }
  return []
}
function filterTree(
  nodes: Sidebar03TreeNode[],
  query: string,
): Sidebar03TreeNode[] {
  if (!query) return nodes
  return nodes.flatMap((node) => {
    const children = filterTree(node.children ?? [], query)
    return node.label.toLocaleLowerCase().includes(query) || children.length
      ? [{ ...node, children }]
      : []
  })
}
type TreeProps = {
  nodes: Sidebar03TreeNode[]
  expanded: string[]
  onExpandedChange: (ids: string[]) => void
  activeId?: string
  query: string
  labels: Sidebar03Labels
  renderLink: (
    node: Sidebar03TreeNode,
    content: React.ReactNode,
  ) => React.ReactNode
}
function Sidebar03Tree({
  nodes,
  expanded,
  onExpandedChange,
  activeId,
  query,
  labels,
  renderLink,
}: TreeProps) {
  const root = React.useRef<HTMLUListElement>(null)
  const [focused, setFocused] = React.useState(activeId)
  const filtered = filterTree(nodes, query.trim().toLocaleLowerCase())
  const visible: { node: Sidebar03TreeNode; parent?: string }[] = []
  function collect(items: Sidebar03TreeNode[], parent?: string) {
    items.forEach((node) => {
      visible.push({ node, parent })
      if (query || expanded.includes(node.id))
        collect(node.children ?? [], node.id)
    })
  }
  collect(filtered)
  const focusId = visible.some(({ node }) => node.id === focused)
    ? focused
    : visible[0]?.node.id
  function focus(id?: string) {
    if (!id) return
    setFocused(id)
    const target = Array.from(
      root.current?.querySelectorAll<HTMLElement>('[role="treeitem"]') ?? [],
    ).find((el) => el.dataset.nodeId === id)
    target?.focus()
  }
  function toggle(id: string) {
    onExpandedChange(
      expanded.includes(id)
        ? expanded.filter((value) => value !== id)
        : [...expanded, id],
    )
  }
  function keydown(event: React.KeyboardEvent, node: Sidebar03TreeNode) {
    if (event.target !== event.currentTarget) return
    const index = visible.findIndex((item) => item.node.id === node.id)
    const open = Boolean(query) || expanded.includes(node.id)
    switch (event.key) {
      case "ArrowDown":
        focus(visible[Math.min(index + 1, visible.length - 1)]?.node.id)
        break
      case "ArrowUp":
        focus(visible[Math.max(0, index - 1)]?.node.id)
        break
      case "Home":
        focus(visible[0]?.node.id)
        break
      case "End":
        focus(visible.at(-1)?.node.id)
        break
      case "ArrowRight":
        if (node.children?.length) {
          if (!open) toggle(node.id)
          else focus(node.children[0]?.id)
        }
        break
      case "ArrowLeft":
        if (node.children?.length && open && !query) toggle(node.id)
        else focus(visible[index]?.parent)
        break
      case "Enter":
        if (node.href)
          event.currentTarget.querySelector<HTMLAnchorElement>("a")?.click()
        else if (node.children?.length) toggle(node.id)
        break
      default:
        return
    }
    event.preventDefault()
    event.stopPropagation()
  }
  function renderNodes(
    items: Sidebar03TreeNode[],
    level: number,
  ): React.ReactNode {
    return items.map((node, index) => {
      const branch = Boolean(node.children?.length)
      const open = Boolean(query) || expanded.includes(node.id)
      const Icon = node.icon ?? FolderIcon
      const content = (
        <>
          <Icon aria-hidden className="size-4 shrink-0" />
          <span className="truncate">{node.label}</span>
          {node.status && (
            <>
              <span
                aria-hidden
                className={cn(
                  "ml-auto size-1.5 shrink-0 rounded-full",
                  node.status === "active"
                    ? "bg-chart-2"
                    : node.status === "paused"
                      ? "bg-chart-4"
                      : "bg-sidebar-foreground/40",
                )}
              />
              <span className="sr-only">{labels[node.status]}</span>
            </>
          )}
          {node.badge !== undefined && (
            <span className="ml-auto text-xs text-sidebar-foreground/60 tabular-nums">
              {node.badge}
            </span>
          )}
        </>
      )
      return (
        <li
          key={node.id}
          data-node-id={node.id}
          role="treeitem"
          aria-selected={node.id === activeId}
          aria-label={node.label}
          aria-level={level}
          aria-posinset={index + 1}
          aria-setsize={items.length}
          aria-expanded={branch ? open : undefined}
          aria-current={node.id === activeId ? "page" : undefined}
          tabIndex={focusId === node.id ? 0 : -1}
          onFocus={(event) => {
            if (event.target === event.currentTarget) setFocused(node.id)
          }}
          onKeyDown={(event) => keydown(event, node)}
          className="rounded-md outline-hidden [&:focus-visible>div]:ring-2 [&:focus-visible>div]:ring-sidebar-ring [&:focus-visible>div]:ring-inset"
        >
          <div
            onMouseDown={(event) => {
              event.preventDefault()
              setFocused(node.id)
              event.currentTarget.parentElement?.focus({ preventScroll: true })
            }}
            className={cn(
              "flex h-8 items-center rounded-md text-sm hover:bg-sidebar-accent pointer-coarse:h-10",
              node.id === activeId &&
                "bg-sidebar-accent font-medium text-sidebar-accent-foreground",
            )}
          >
            {branch ? (
              <span
                aria-hidden
                onClick={() => toggle(node.id)}
                className="flex size-6 shrink-0 cursor-pointer items-center justify-center"
              >
                <ChevronRightIcon
                  className={cn("size-3", open && "rotate-90")}
                />
              </span>
            ) : (
              <span className="w-6 shrink-0" />
            )}
            {node.href ? (
              renderLink(node, content)
            ) : (
              <span
                onClick={() => branch && toggle(node.id)}
                className="flex min-w-0 flex-1 cursor-pointer items-center gap-2 pr-2"
              >
                {content}
              </span>
            )}
          </div>
          {branch && open && (
            <ul
              role="group"
              className="ml-3 border-l border-sidebar-border pl-2"
            >
              {renderNodes(node.children!, level + 1)}
            </ul>
          )}
        </li>
      )
    })
  }
  return (
    <div data-slot="sidebar-03-tree" className="p-2">
      {visible.length ? (
        <ul ref={root} role="tree" aria-label={labels.tree}>
          {renderNodes(filtered, 1)}
        </ul>
      ) : (
        <p
          role="status"
          className="px-3 py-6 text-sm leading-6 text-sidebar-foreground/60"
        >
          {labels.empty}
        </p>
      )}
    </div>
  )
}
export { Sidebar03Tree, findPath }

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }
